export const STR = { it, en, de, fr, es, pt };
export const CODES = Object.keys(STR);
export const LOCALES = { it: "it-IT", en: "en-GB", de: "de-DE", fr: "fr-FR", es: "es-ES", pt: "pt-BR" };

/** A language's strings, each missing key falling back to English. */
export function strings(lang) {
  return { ...en, ...(STR[lang] ?? {}) };
}
